def render_row_mixed(cells, widths, aligns):
    parts = []
    for c, w, a in zip(cells, widths, aligns):
        if a == 'l':
            parts.append(c.ljust(w))
        elif a == 'r':
            parts.append(c.rjust(w))
        else:
            parts.append(c.center(w))
    return " ".join(parts)

def render_grid_row(cells, widths):
    parts = [c.ljust(w) for c, w in zip(cells, widths)]
    return "| " + " | ".join(parts) + " |"

def render_row_truncate_pad(cells, widths):
    parts = []
    for c, w in zip(cells, widths):
        if len(c) > w:
            parts.append(c[:w])
        else:
            parts.append(c.ljust(w))
    return " ".join(parts)

def wrap_greedy(text, width):
    words = text.split()
    lines = []
    cur = ""
    for word in words:
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= width:
            cur += " " + word
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    return lines

def wrap_break_long_words(text, width):
    words = text.split()
    lines = []
    cur = ""
    for word in words:
        while len(word) > width:
            if cur:
                lines.append(cur)
                cur = ""
            lines.append(word[:width])
            word = word[width:]
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= width:
            cur += " " + word
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    return lines

def wrap_fixed_lines(text, width, max_lines):
    words = text.split()
    lines = []
    cur = ""
    for word in words:
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= width:
            cur += " " + word
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    if len(lines) > max_lines:
        lines = lines[:max_lines]
        last = lines[-1]
        if len(last) + 3 <= width:
            lines[-1] = last + "..."
        else:
            lines[-1] = last[:max(0, width - 3)] + "..."
    return lines

def wrap_preserve_paragraphs(text, width):
    paragraphs = text.split("\n")
    result = []
    for para in paragraphs:
        words = para.split()
        lines = []
        cur = ""
        for word in words:
            if not cur:
                cur = word
            elif len(cur) + 1 + len(word) <= width:
                cur += " " + word
            else:
                lines.append(cur)
                cur = word
        if cur:
            lines.append(cur)
        if not lines:
            lines = [""]
        result.append("\n".join(lines))
    return "\n".join(result)

def wrap_with_indent(text, width, indent):
    words = text.split()
    lines = []
    cur = ""
    for word in words:
        limit = width if not lines else width - indent
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= limit:
            cur += " " + word
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    out = []
    for i, line in enumerate(lines):
        out.append(line if i == 0 else " " * indent + line)
    return out

def wrap_count_lines(text, width):
    words = text.split()
    if not words:
        return 0
    lines = 1
    cur_len = len(words[0])
    for word in words[1:]:
        if cur_len + 1 + len(word) <= width:
            cur_len += 1 + len(word)
        else:
            lines += 1
            cur_len = len(word)
    return lines

def wrap_to_width_char(text, width):
    if width <= 0:
        return []
    return [text[i:i + width] for i in range(0, len(text), width)]

def wrap_bullet(text, width, bullet):
    prefix = bullet + " "
    words = text.split()
    lines = []
    cur = ""
    limit = width - len(prefix)
    for word in words:
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= limit:
            cur += " " + word
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    indent = " " * len(prefix)
    out = []
    for i, line in enumerate(lines):
        out.append((prefix if i == 0 else indent) + line)
    return out

def indent_lines(text, n):
    lines = text.split("\n")
    return "\n".join((" " * n + line) if line else line for line in lines)

def dedent_lines(text, n):
    out = []
    for line in text.split("\n"):
        count = 0
        while count < n and count < len(line) and line[count] == " ":
            count += 1
        out.append(line[count:])
    return "\n".join(out)

def common_dedent(lines):
    non_empty = [l for l in lines if l.strip() != ""]
    if not non_empty:
        return list(lines)
    min_indent = min(len(l) - len(l.lstrip(" ")) for l in non_empty)
    return [l[min_indent:] if l.strip() != "" else l for l in lines]
